    for (size_t i=0;i<n;i++) {
        unsigned char ch=(unsigned char)text[i];
        if (!((ch>='a'&&ch<='z')||(ch>='A'&&ch<='Z')||(ch>='0'&&ch<='9')||ch=='_'||ch=='-')) return 0;
