    if(retry_count && strcmp(request.op,"PING") && strcmp(request.op,"BALANCE") && strcmp(request.op,"TOP") && strcmp(request.op,"HISTORY")) {
        fprintf(stderr,"write retries require durable event idempotency\n"); return 2;
