    int port=0,upstream=0;
    if(argc!=3 || !parse_number(argv[1],65535,&port) || !parse_number(argv[2],65535,&upstream) || !upstream) {
        fprintf(stderr,"Usage: gateway LISTEN_PORT SERVICE_PORT\n"); return 2;
