    CHECK(!parse_number("999999999999999999999999",65535,&number));
    CHECK(!parse_number("-1",65535,&number));
    CHECK(!parse_number("1x",65535,&number));
    puts("PROTOCOL TESTS PASSED"); return 0;
}

